def transform(grid):
    counts = {}
    for r in grid:
        for c in r:
            counts[c] = counts.get(c, 0) + 1

    # Determine background color (most frequent)
    bg = max(counts, key=counts.get) if counts else 0

    # Identify separator rows (uniform color different from background)
    sep_rows = []
    for r in range(len(grid)):
        if len(grid[r]) > 0:
            row_val = grid[r][0]
            if row_val != bg and all(cell == row_val for cell in grid[r]):
                sep_rows.append(r)

    # Identify separator columns (uniform color different from background)
    sep_cols = []
    if len(grid) > 0:
        num_cols = len(grid[0])
        for c in range(num_cols):
            # Check if column is uniform and not part of background
            if all(grid[r][c] == grid[0][c] and grid[r][c] != bg for r in range(len(grid))):
                sep_cols.append(c)

    # Determine ranges for row blocks
    ranges_r = []
    current_row = 0
    for r in sep_rows:
        ranges_r.append((current_row, r))
        current_row = r + 1
    ranges_r.append((current_row, len(grid)))

    # Determine ranges for column blocks
    ranges_c = []
    current_col = 0
    for c in sep_cols:
        ranges_c.append((current_col, c))
        current_col = c + 1
    ranges_c.append((current_col, num_cols))

    # Construct output grid based on block properties
    output = []
    for r_idx, (r1, r2) in enumerate(ranges_r):
        row_out = []
        for c_idx, (c1, c2) in enumerate(ranges_c):
            # Collect all pixels in the block
            block_pixels = []
            for r in range(r1, r2):
                for c in range(c1, c2):
                    block_pixels.append(grid[r][c])

            # Count non-background pixels (noise)
            non_bg_count = sum(1 for pixel in block_pixels if pixel != bg)

            # Odd count -> Background Color, Even count -> 1
            if non_bg_count % 2 == 1:
                row_out.append(bg)
            else:
                row_out.append(1)
        output.append(row_out)

    return output
